.hero-banner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  margin: 0 auto;
  border-radius: 12px;
  cursor: pointer;
  box-sizing: border-box;
}

/* Navigation Header */
.navbar {
  display: flex;
  justify-content: space-between;
  padding: 1rem 2rem;
}

.navbar .brand-logo {
  font-weight: bold;
  font-size: 1.25rem;
}

.navbar .nav-menu {
  display: flex;
  gap: 1.5rem;
}

.navbar .nav-menu a.nav-link {
  color: #333;
  text-decoration: none;
}

.navbar .cta-button {
  background: #0070f3;
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 4px;
}

/* Card Showcase Grid */
.showcase-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.showcase-grid .product-card {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 1.5rem;
}

.product-card .card-badge {
  background: #f1f5f9;
  font-size: 0.75rem;
}

.product-card h3.card-title {
  font-size: 1.125rem;
}

.product-card p.card-description {
  color: #64748b;
}

